                      className="h-8 px-2 text-xs"
                    >
                      Prev
                    </Button>
                    {Array.from({ length: totalPages }, (_, i) => i)
                      .filter((i) => {
                        if (totalPages <= 7) return true
                        if (i === 0 || i === totalPages - 1) return true
                        if (Math.abs(i - pageIndex) <= 1) return true
                        return false
                      })
                      .map((i, idx, arr) => {
                        const showEllipsis = idx > 0 && i - arr[idx - 1] > 1
                        return (
